DROP SCHEMA public CASCADE;
CREATE SCHEMA public;

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) NOT NULL,
  "email_verified_at" timestamp,
  "terms_accepted" bool,
  "terms_version" date,
  "password_hash" varchar(255) NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp,
  "last_seen_at" timestamp,
  "account_status" varchar(255)
);

CREATE TABLE "user_profiles" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer UNIQUE NOT NULL,
  "background_art" int DEFAULT 1,
  "music_on" bool DEFAULT true,
  "country" char(2),
  "timezone" timestamp
);

CREATE TABLE "site_events" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer,
  "event_type_id" integer NOT NULL,
  "activity_id" integer,
  "emotion_id" integer,
  "created_at" timestamp
);

CREATE TABLE "event_types" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(255) UNIQUE
);

CREATE TABLE "favorites" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "created_at" timestamp,
  constraint uq_user_favorite UNIQUE (user_id, activity_id)
);

CREATE TABLE "upvotes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "created_at" timestamp,
  constraint uq_user_upvote UNIQUE (user_id, activity_id)
);

CREATE TABLE "downvotes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "created_at" timestamp,
  constraint uq_user_downvote UNIQUE (user_id, activity_id)
);

CREATE TABLE "activities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(255) UNIQUE NOT NULL,
  "description" text,
  "min_time" interval,
  "max_time" interval,
  "screen_only" bool,
  "group_only" bool,
  "requires_supplies" bool,
  "published" bool DEFAULT false,
  "created_at" timestamp
);

CREATE TABLE "more_specific_activities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "title" varchar(255),
  "description" text,
  "layout_id" integer,
  "min_time" interval,
  "max_time" interval,
  "requires_supplies" bool,
  "created_at" timestamp
);

CREATE TABLE "genres" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(255) UNIQUE
);

CREATE TABLE "activity_genres" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "genre_id" integer NOT NULL,
  "activity_id" integer NOT NULL
);

CREATE TABLE "abilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(255) UNIQUE,
  "description" text
);

CREATE TABLE "user_abilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "ability_id" integer NOT NULL
);

CREATE TABLE "activity_abilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "ability_id" integer NOT NULL
);

CREATE TABLE "specific_activity_abilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "more_option_id" integer NOT NULL,
  "ability_id" integer NOT NULL
);

CREATE TABLE "genre_abilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "genre_id" integer NOT NULL,
  "ability_id" integer NOT NULL
);

CREATE TABLE "emotions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(255) UNIQUE
);

CREATE TABLE "activity_emotions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activity_id" integer NOT NULL,
  "emotion_id" integer NOT NULL,
  "relevance_score" integer NOT NULL
);

ALTER TABLE "user_profiles" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "site_events" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "site_events" ADD FOREIGN KEY ("event_type_id") REFERENCES "event_types" ("id") DEFERRABLE INITIALLY IMMEDIATE;

