ALTER TABLE "activity_genres" ADD FOREIGN KEY ("activity_id") REFERENCES "activities" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "activity_emotions" ADD FOREIGN KEY ("emotion_id") REFERENCES "emotions" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "activity_emotions" ADD FOREIGN KEY ("activity_id") REFERENCES "activities" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "genre_abilities" ADD FOREIGN KEY ("genre_id") REFERENCES "genres" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "specific_activity_abilities" ADD FOREIGN KEY ("more_option_id") REFERENCES "more_specific_activities" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "specific_activity_abilities" ADD FOREIGN KEY ("ability_id") REFERENCES "abilities" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "activity_abilities" ADD FOREIGN KEY ("activity_id") REFERENCES "activities" ("id") DEFERRABLE INITIALLY IMMEDIATE;

